# ruff: noqa: E501
"""Director-style English LTX-2.3 prompts for *Deep Space*, episode one."""

from __future__ import annotations

from dataclasses import dataclass

STYLE_ANCHOR = (
    "Photorealistic dark historical fantasy drama with cinematic 35mm film grain, restrained natural motion, "
    "and precise physical continuity. The primary location is a cramped wooden smuggler ship hold with wet dark "
    "timbers, mold-stained walls, shallow dirty seawater, a low ceiling, and three brass kerosene lanterns on chains. "
    "Use Rembrandt chiaroscuro, warm amber practical lantern light, deep brown shadows, and no readable on-screen "
    "text or logos. Shen Sheng is a lean young Asian man in his twenties with high cheekbones, pale exhausted skin, "
    "wet untidy black hair on his forehead, and a soaked patched gray-brown coarse tunic. "
)


@dataclass(frozen=True)
class ScenePrompt:
    number: int
    title: str
    duration_seconds: float
    prompt: str

    @property
    def full_prompt(self) -> str:
        return STYLE_ANCHOR + self.prompt


SCENES: tuple[ScenePrompt, ...] = (
    ScenePrompt(1, "Thrown awake", 6.0, "The camera begins in a 35mm overhead wide shot threaded between low ceiling beams, slowly tilting down past three swinging lanterns whose amber light skates across wet timber and oily water. Shen Sheng lies face-down in the foreground, motionless. A towering muscular Black sailor enters from frame right, boots breaking the water with heavy splashes; he grips Shen Sheng's collar, hauls him halfway upright, then throws him back down. Keep the lighting entirely practical, with each lantern swing briefly exposing the sailor's scarred cheek and leaving Shen Sheng in shadow. The sound is only hull groans, distant waves, dripping water, wet cloth and boots; no music enters. The camera settles as Shen Sheng's right palm presses into the water and concentric ripples spread outward; the shot ends on that trembling hand and the water sound carries forward."),
    ScenePrompt(2, "Wake and humiliation", 6.0, "The camera starts at water level on the same right hand and follows the ripples backward in a slow 40mm dolly to a low medium shot. Shen Sheng drags himself upright, coughs dirty water from his mouth, and lets soaked hair hide his eyes while the tall sailor remains soft and imposing at frame right. A lantern's side light cuts across only half of Shen Sheng's face; when the sailor walks past, his body blocks that light for one beat. In a coarse low English voice the sailor says, \"Yellow rat, tell me if you cannot hold on. I will put you out of your misery.\" He laughs once and exits toward the right darkness. The sound layers splashing boots, Shen Sheng's ragged breath, and a barely audible low ship-bass drone that begins beneath the hull creaks. Shen Sheng slowly raises only his eyes after the sailor leaves; the camera holds his rightward gaze, and the shot ends on that unbroken eyeline."),
    ScenePrompt(3, "Memory breach", 7.0, "The camera preserves Shen Sheng's rightward eyeline in an 85mm profile close-up as he leans his wet back against the bulkhead, then makes a slow deliberate push toward his closing eyes. Lantern light flickers over his cheekbone, then drains away on one deep heartbeat. Hard cut into a fractured memory montage: a rusted orphanage gate closes under cold fluorescent light; blue monitor light catches young hands racing on a keyboard; a saturated neon future city and a magical battlefield flash past in whip-pan fragments; a thinner Shen Sheng runs through a warm ochre medieval street; a pale hand coughs dark red blood beside a hospital bed. The camera motion becomes unstable, with brief white flashes and rack-focus smears, then every color fragment contracts into a single dark pupil. The sound transforms from water drips and breath into broken electronic pulses, keyboard taps, running steps, coughs and one amplified heartbeat; the score is a fragmented synth motif that abruptly cuts. The montage ends in black on the heartbeat, making this a deliberate hard scene transition."),
    ScenePrompt(4, "Recognition", 6.0, "From black, the camera hard cuts to an extreme 100mm close-up of Shen Sheng's pupil; the amber lantern flame trembles as a tiny reflection inside it. The camera eases backward to a tight half-length portrait while he opens his eyes, holds his breath, wipes water from his cheek with the back of his hand, and lets the smallest forbidden smile appear before suppressing it. A left-overhead lantern light travels slowly across his face, turning confusion into controlled focus without changing the cramped setting. The sound restores the ship hold one element at a time: a water drop, a hull groan, then his fingertip tapping a muted three-beat rhythm on his knee. A low sustained cello note replaces the broken synth but stays below the practical sound. Shen Sheng looks down at the tapping fingers; the camera follows, and the shot ends in close-up on the measured hand rhythm."),
    ScenePrompt(5, "The player studies the board", 7.0, "The camera starts in close-up on Shen Sheng's tapping fingers, then tilts and rises into a 50mm medium shot that makes a slow clockwise half-orbit around him. He keeps his shoulders slack and performs weakness for the room, but his eyes calmly inspect three people as the orbit reveals them in turn: Michael, broad and tense in a white undershirt; a middle-aged Black woman clutching a worn Bible; and George, a gaunt white man crouched in shadow. Each face receives one passing stripe of amber lantern light and falls back into darkness. In the oily puddle beside Shen Sheng, a faint abstract non-readable blue glow breathes once, reflected across his knuckles. The sound is the continuing finger rhythm, distant murmurs and the cello note, with no dialogue. George suddenly inhales sharply and rises in the background; the camera stops its orbit on that movement, and the shot ends on his intake of breath."),
    ScenePrompt(6, "George's warning", 7.0, "The camera begins on George's sharp inhale and backs away from his chest in a handheld 50mm medium shot with restrained breath-like sway. He stands too fast, points into the black end of the hold, swallows, glances over his shoulder, then points again as a side lantern throws his shaking silhouette huge across the bulkhead. The amber light trembles around his bloodshot eyes while the rest of the crowd retreats a half-step. Under the water drips, an unstable low-string score enters almost inaudibly. In high strained English, with a pause after each fearful phrase, George says, \"There is a ghost... Little Tom died the night old John came back. Blue and violet... it smiled, and Tom died.\" His fingers shake on the word \"violet\"; nearby people gasp and the woman raises her Bible from the lower edge of frame. George's last breath hangs over the sound as the camera follows the rising Bible; the shot ends on its upward motion."),
    ScenePrompt(7, "False protection", 7.0, "The camera begins on the Bible lifted in the same vertical axis, then makes a smooth 50mm pan to the woman's face and onward to a thin southern European skeptic leaning against a post. Lantern chains swing harder as the argument spreads, giving each speaker a different moving pattern of light and shadow. The woman grips the worn cover until her knuckles pale, looks toward the stairwell, and says in a loud wavering English voice, \"Father Evan is a proper priest from Coman Town. The church will protect us.\" The skeptic exhales through his nose, folds his arms, and answers, \"A priest cannot save you from that.\" From deeper crowd layers, short frightened fragments overlap but stay distinguishable: \"Blue-violet,\" \"It kills,\" and \"The priest will help us.\" The low strings tighten beneath clattering lantern chains, crowd voices and water; Shen Sheng remains still at frame edge watching. The argument swells to its loudest point, and the shot ends just before a sound from above interrupts it."),
    ScenePrompt(8, "Gunshots and stillness", 6.0, "The camera hard cuts to a locked 24mm wide tableau that maps the entire hold and preserves the positions established in the argument. Four or five deafening gunshots explode from the deck directly above, followed by two distant screams; the camera does not move. The score is cut instantly at the first shot, leaving only ringing aftermath. Every person freezes in an unfinished gesture: George's mouth open and hand raised, the woman's Bible slipping between her fingers, the skeptic half-turned, Shen Sheng's body coiling into a defensive stance. Lantern chains stop swinging as if time is held. One backlit water drop falls through the foreground and strikes a puddle with an amplified tick; its ripple becomes the only movement. The amber light dims at the frame edges, and the shot ends on the circular ripple while the isolated water sound continues."),
    ScenePrompt(9, "The stairwell", 7.0, "The camera starts behind Shen Sheng's shoulder, using a 50mm over-the-shoulder composition where his wet hair and dark silhouette frame the distant stairwell. It begins focused on his shoulder, then slowly racks focus onto the faint opening above. The sound is the same single water drip from the previous shot keeping time; there is no score. George, blurred in the midground, lowers his hand and whispers in a nearly voiceless English murmur, \"Could it be... the ghost?\" A soft abstract blue non-readable progress glow brushes Shen Sheng's cheek and disappears. Shen Sheng rises from a half-kneel without taking his eyes off the stairs; his breath is controlled but visible. The camera pans slightly left without cutting as Michael stands from the crowd on the same screen side. The shot ends with Michael's shoulder crossing into the stairwell's weak light."),
    ScenePrompt(10, "Michael climbs", 7.0, "The camera maintains the leftward screen direction in a low-angle 35mm shot looking up the wooden ladder toward a narrow shaft of deck light. Michael steps into the light, grips a rung with one hand, looks once toward the black opening, and says in a hoarse steady English voice, \"No. I am not mad. It is too cramped in here.\" After a measured breath he climbs one rung at a time; the camera makes a short, cautious upward tracking move with him rather than overtaking him. His broad back blocks the light and throws a long moving shadow down over the silent crowd. Two migrants enter from below and follow at a distance. The sound has no melody, only heavy breathing, boots, wet wood groaning and a very low tension drone returning underneath. The camera holds on Michael's boot compressing the highest visible plank; the shot ends with the wood giving a long strained creak."),
    ScenePrompt(11, "The fall", 5.0, "The camera match-cuts from the boot and creaking plank to a high 28mm angle above the ladder. A sudden tearing sound snaps through the score; Michael and the two followers jerk once and fall downward like broken marionettes. The camera dives a short distance with them, then stabilizes immediately on the lantern-lit floor so the motion remains legible. Three impacts land in sequence with splintering wood, fabric scrape and shocked cries. Do not show a complex tumble: show Michael sprawled on top, one smaller man with a bent arm, and two withered bodies beneath. The warm lantern light is still present but begins to look sickly pale. The camera pushes into Michael's wide open eye as he stares at the ceiling; his first breath leaves his mouth as a thin white plume. The score drops to near silence, and the shot ends on that freezing breath."),
    ScenePrompt(12, "Cold enters the hold", 8.0, "The camera begins at floor height beside Michael's white breath and makes a slow lateral 40mm glide past the blurred fallen bodies toward the people pressed against the bulkhead. With each breath, more white fog gathers in the frame; tiny ice crystals form on wet wood and catch the lens in shallow depth of field. The three lanterns remain visible in the background, but blue-violet reflected light progressively overwhelms their amber light from above, one pool of warm light at a time. Nobody speaks; actors recoil in small readable gestures, hands cover mouths and knees buckle. The sound starts with the previous breath, then adds a sub-bass hum, distant bow-on-metal friction and fine ice crackle. A wordless choral BGM rises so quietly that it feels like the room itself is resonating. The camera tilts toward a ceiling crack where cold violet light spills down; the shot ends on that widening beam."),
    ScenePrompt(13, "The ghost descends", 10.0, "The camera begins on the same ceiling crack in a 28mm low-angle shot, then slowly tilts and cranes backward as a translucent blue-violet humanoid ghost phases down through the wooden ceiling without a cut. Its lower body dissolves into smoke, small bone spurs flex outward along its distorted silhouette, and hollow eye sockets churn with viscous violet energy. Its cold bioluminescent light becomes the key light for the entire hold, turning every wet surface cyan-purple and reducing the lanterns to faint amber embers. In the lower frame, migrants retreat, kneel or freeze; Shen Sheng presses his back flat to the bulkhead and follows the apparition with his eyes. The sound is the continuing sub-bass hum, ice crystals, a slowly swelling wordless choir and frightened breath, with no dialogue. The ghost scans the room in one slow arc, then stops and turns toward Shen Sheng; the camera holds its empty sockets until violet light fills the frame. The shot ends inside that violet reflection."),
    ScenePrompt(14, "Ninety-nine percent", 7.0, "The camera match-cuts from the violet reflection to a 100mm extreme close-up of Shen Sheng's eye, then eases back only enough to reveal his split-lit face: cold blue-violet key light on one side, the final weak amber lantern light on the other. Abstract non-readable red pulses flicker across the moisture in his eyes; no literal interface text is shown. The choir BGM thins and suddenly disappears before the error message, leaving the hum and his breathing. A cold synthesized English system voice speaks in measured broken segments, \"Connection... ninety-nine percent... load failed... reconnecting.\" Shen Sheng's gaze flicks from the invisible red pulses to the ghost, his throat tightens, and a bitter almost-laugh catches before it can become sound. The camera makes a slow final push as he turns his head toward the ghost. The shot ends on the completed head turn, carrying the hum and alarm beep forward."),
    ScenePrompt(15, "There really is a ghost", 6.0, "The camera continues Shen Sheng's head turn in a 35mm over-the-shoulder composition, placing his wet profile in the right foreground and the ghost centered deeper in the blue-violet hold. It makes a slow inexorable push as the distance between them feels smaller; cold fog rolls around Shen Sheng's shoulder and the ghost's bone spurs open one degree farther. The remaining amber light fades entirely, leaving the ghost as the only source. Shen Sheng's back touches the bulkhead, he releases one short dry breath of laughter, then in low cracked English says, \"There really is a ghost.\" The sound layers the alarm beep, sub-bass hum, wordless choir and a single heavy heartbeat; after his line, the choir, alarm and hum peel away one by one until only the heartbeat remains. The camera holds his bitter side profile as violet light swallows the frame; the shot ends in a hard fade to black on the final heartbeat."),
)


